class Resource extends Base {
 mount(){this.items??=[{title:'A quieter kind of studio.',tag:'SPACE / 2026',body:'We began with a room and a window. The work was to let the light do more of the talking.'},{title:'Objects for the long way home.',tag:'OBJECT / 2026',body:'Useful things with a little irregularity. Made to be carried, repaired, and kept.'},{title:'Notes from an open field.',tag:'EDITORIAL / 2026',body:'A collection of observations on places that ask you to slow down.'}];this.opened=-1;this.render(`<section class="scene"><header><span class="label">AN INDEX OF CONSIDERED THINGS</span><h2>Some stories unfold.</h2></header><div class="stack-list">${this.items.map((item,i)=>`<article style="--tone:${['#58715e','#8a6a56','#626d82'][i%3]}"><button data-index="${i}" aria-expanded="false" aria-controls="body-${i}"><span class="number">0${i+1}</span><span><small>${escape(item.tag)}</small><strong>${escape(item.title)}</strong></span><b aria-hidden="true">+</b></button><div id="body-${i}" class="body" hidden><div class="art" aria-hidden="true"><i></i><i></i></div><p>${escape(item.body)}</p></div></article>`).join('')}</div><footer>OPEN A CHAPTER / TAKE YOUR TIME</footer></section>`,`.scene{padding:30px 24px;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);min-height:500px}h2{font:400 clamp(25px,4vw,37px) Georgia;margin:12px 0 27px}.stack-list{display:flex;flex-direction:column;gap:11px}article{border:1px solid var(--line);border-radius:11px;background:linear-gradient(100deg,color-mix(in srgb,var(--tone) 15%,var(--panel)),var(--panel));overflow:hidden}article>button{display:flex;align-items:center;gap:16px;width:100%;border:0;background:none;text-align:left;padding:22px 20px}.number{font:11px ui-monospace;color:var(--muted)}button>span:nth-child(2){flex:1}button small{font-size:8px;letter-spacing:1.3px;color:var(--muted);display:block;margin-bottom:7px}button strong{font:400 clamp(17px,3vw,23px) Georgia}button b{font-size:24px;font-weight:300;color:var(--accent)}.body{display:grid;grid-template-columns:1fr 1.5fr;gap:23px;padding:0 22px 23px}.body[hidden]{display:none}.body p{font-size:12px;color:var(--muted);line-height:1.9;align-self:center}.art{min-height:110px;background:var(--tone);border-radius:6px;position:relative;overflow:hidden}.art i{position:absolute;width:75px;height:95px;left:30%;top:24%;background:#d5dcc699;border-radius:50% 50% 0 0;transform:rotate(-22deg)}.art i+i{left:55%;top:39%;opacity:.5}footer{margin-top:23px;font-size:7px;letter-spacing:1.5px;color:var(--muted)}@media(max-width:480px){.scene{padding:25px 16px}article>button{padding:20px 14px;gap:11px}.body{gap:14px;padding:0 15px 20px;grid-template-columns:1fr}.art{min-height:90px}.body p{font-size:11px}}`);this.listen(this.$('.stack-list'),'click',e=>{const button=e.target.closest('button');if(button)this.open(Number(button.dataset.index));});}
 open(index){const was=this.opened;this.opened=was===index?-1:index;this.$$('article').forEach((node,i)=>{const active=i===this.opened;node.querySelector('button').setAttribute('aria-expanded',String(active));node.querySelector('button b').textContent=active?'−':'+';node.querySelector('.body').hidden=!active;if(active)this.tween(node.querySelector('.body'),[{opacity:.1,transform:'translateY(-9px)'},{opacity:1,transform:'none'}]);});this.emit('stack-change',{index,open:this.opened===index});}
}
